-- 자동 생성 파일: node scripts/generate-seed-sql.mjs (직접 수정하지 말 것)
-- 0001_init.sql 실행 후 SQL Editor에서 실행. 여러 번 실행해도 안전하다.
-- 작가 내용은 더미(작가명만 실명). edit_token은 DB가 랜덤 생성한다.

insert into public.settings (id, exhibition_title, period_start, period_end, venue, address, map_url, hours, closed_dates, opening_at, admission, intro_text)
values (1, 'Overload: 감정의 풍경', '2026-12-22', '2026-12-31', '역삼1동복합문화센터 1층', '서울 강남구 역삼로7길 16', 'https://map.naver.com/p/search/%EC%84%9C%EC%9A%B8%20%EA%B0%95%EB%82%A8%EA%B5%AC%20%EC%97%AD%EC%82%BC%EB%A1%9C7%EA%B8%B8%2016', '매일 10:00–18:00 (12월 22일은 14:00 오픈)', array['2026-12-25']::date[], '2026-12-22T14:00:00+09:00', '무료', '(임시 서문) 우리는 매일 감당하기 어려운 양의 감정을 마주한다. 기쁨과 불안, 피로와 설렘이 한꺼번에 밀려드는 시대에, 감정은 종종 넘쳐흐르고 과부하된다.

《Overload: 감정의 풍경》은 여덟 명의 작가가 각자의 언어로 그려낸 감정의 지형도이다. 넘쳐흐르는 감정을 억누르기보다 그것이 만들어내는 풍경을 가만히 들여다보고자 한다.')
on conflict (id) do nothing;

insert into public.artists (slug, sort_order, draft, published, published_at)
values ('kim-minae', 1, $json${"name":"김미내","profile_image":"/sample/kim-minae/profile.webp","bio":"(더미 소개글) 일상에서 넘쳐흐르는 감정의 결을 붙잡아 화면 위에 펼쳐 놓는다. 감각이 과부하되는 순간과 그 이후에 남는 고요를 함께 기록하며, 보이지 않는 감정의 풍경을 색과 형태로 번역하는 작업을 이어오고 있다.","education":"(더미) OO대학교 대학원 회화과 졸업\n(더미) OO대학교 미술대학 서양화과 졸업","exhibitions":"개인전\n2025 (더미) 「감정의 온도」, 갤러리 OO, 서울\n\n단체전\n2026 Overload: 감정의 풍경, 역삼1동복합문화센터, 서울\n2024 (더미) 「사이의 풍경」, OO아트스페이스, 서울","website":"https://example.com","works":[{"id":"w1","image_full":"/sample/kim-minae/w1_full.webp","image_thumb":"/sample/kim-minae/w1_thumb.webp","width":1280,"height":1600,"title":"무제","year":"2026","medium":"캔버스에 유채","size":"80 × 100 cm","etc":"","description":"(더미 작품 설명) 감정이 한계를 넘어 흘러넘치는 순간을 겹겹의 색면으로 표현했다.\n가까이서 볼 때와 멀리서 볼 때 서로 다른 풍경이 드러나도록 구성했다.","photo_credit":"(더미) 홍길동"},{"id":"w2","image_full":"/sample/kim-minae/w2_full.webp","image_thumb":"/sample/kim-minae/w2_thumb.webp","width":1600,"height":1067,"title":"과잉의 밤","year":"2026","medium":"종이에 수채","size":"60 × 40 cm","etc":"(더미) 에디션 1/3","description":"(더미 작품 설명) 감정이 한계를 넘어 흘러넘치는 순간을 겹겹의 색면으로 표현했다.\n가까이서 볼 때와 멀리서 볼 때 서로 다른 풍경이 드러나도록 구성했다.","photo_credit":""},{"id":"w3","image_full":"/sample/kim-minae/w3_full.webp","image_thumb":"/sample/kim-minae/w3_thumb.webp","width":1600,"height":1600,"title":"흘러넘치는 오후","year":"2026","medium":"장지에 먹, 채색","size":"","etc":"","description":"","photo_credit":"(더미) 홍길동"},{"id":"w4","image_full":"/sample/kim-minae/w4_full.webp","image_thumb":"/sample/kim-minae/w4_thumb.webp","width":1067,"height":1600,"title":"잔향","year":"2024–2026","medium":"디지털 프린트","size":"40 × 60 cm","etc":"","description":"(더미 작품 설명) 감정이 한계를 넘어 흘러넘치는 순간을 겹겹의 색면으로 표현했다.\n가까이서 볼 때와 멀리서 볼 때 서로 다른 풍경이 드러나도록 구성했다.","photo_credit":""}]}$json$::jsonb, $json${"name":"김미내","profile_image":"/sample/kim-minae/profile.webp","bio":"(더미 소개글) 일상에서 넘쳐흐르는 감정의 결을 붙잡아 화면 위에 펼쳐 놓는다. 감각이 과부하되는 순간과 그 이후에 남는 고요를 함께 기록하며, 보이지 않는 감정의 풍경을 색과 형태로 번역하는 작업을 이어오고 있다.","education":"(더미) OO대학교 대학원 회화과 졸업\n(더미) OO대학교 미술대학 서양화과 졸업","e